  let x = E[0] + p.vx * age * L.k, y = E[1] + (p.fis ? (-8 * age + 2.2 * age * age) : (p.vy * age + .6 * age * age)) * L.k;
  const [cx, cy] = S2([0, 0]), KR = (SG.band1 + 14) * L.k; const dx = x - cx, dy = y - cy, d = Math.hypot(dx, dy); if (d < KR) { const k = KR / (d || 1); x = cx + dx * lerp(1, k, .92); y = cy + dy * lerp(1, k, .92); }
  const fy = L.floorY; if (y > fy - 6) { const over = y - (fy - 6); y = fy - 6 + over * .1; x += clamp((x - L.cx) / (36 * L.k), -1, 1) * over * .75; } /* v6.3 (verify v6.2 r2 art-bar: a floor puff swapped shape in one frame, menu 2.333 / boot 3.133 / dread 3.900): the push along the floor flipped sign when a puff crossed the centre line (a 42 px jump); it now passes smoothly through 0 there */
