const SCR = {}; function scratch(key, W, H) { let c = SCR[key]; if (!c || c.width !== W || c.height !== H) c = SCR[key] = mk(W, H); const q = c.getContext('2d'); q.setTransform(1, 0, 0, 1, 0, 0); q.globalAlpha = 1; q.globalCompositeOperation = 'source-over'; q.filter = 'none'; q.clearRect(0, 0, W, H); return c; }
const flushOn = q => { q.fillRect(0, 0, 0, 0); }; // any non-puff draw flushes that context's pending cel-smoke batch (anime_v6.js batcher)
// draw fn(q) on a scratch canvas with g's transform, then lay it on g with alpha a (the whole layer fades: no cel pass or threshold pops)
function asLayer(g, a, key, fn) { const W = g.canvas.width, H = g.canvas.height, c = scratch(key, W, H), q = c.getContext('2d'); q.setTransform(g.getTransform()); fn(q); flushOn(q);
  g.save(); g.setTransform(1, 0, 0, 1, 0, 0); g.globalAlpha = clamp(a, 0, 1); g.drawImage(c, 0, 0); g.restore(); }

